var VERSION = "2.1.0";
  fetch("https://raw.githubusercontent.com/ol1oly/My-future-bulk-upload/main/VERSION", { cache: "no-store" })
    .then(function (r) { return r.ok ? r.text() : ""; })
    .then(function (v) {
      v = v.trim();
      var a = v.split(".").map(Number), b = VERSION.split(".").map(Number), newer = false;
      for (var i = 0; i < 3; i++) { if (a[i] !== b[i]) { newer = a[i] > b[i]; break; } }
      if (!/^\d+\.\d+\.\d+$/.test(v) || !newer) return;
      var el = document.getElementById("newer");
      el.innerHTML = "Version " + v + " is out and this page is older. <a href=\"https://github.com/ol1oly/My-future-bulk-upload\">Download the latest install page</a>.";
      el.hidden = false;
    }, function () {});
  var code = new TextDecoder().decode(Uint8Array.from(atob(""), function(c){ return c.charCodeAt(0); }));
  var url = "javascript:" + code;
  var smart = new TextDecoder().decode(Uint8Array.from(atob(""), function(c){ return c.charCodeAt(0); }));
  document.getElementById("bmSmart").href = "javascript:" + encodeURIComponent(smart);
  document.getElementById("bm").href = url;
  document.getElementById("src").value = code;
  document.getElementById("copy").addEventListener("click", function(){
    var btn = this;
    navigator.clipboard.writeText(url).then(function(){ btn.textContent = "Copied. Make a new bookmark and paste it as the URL."; },
      function(){ btn.textContent = "Copy failed. Use the console option below."; });
  });
